validator:
function validate(input) {
  const [{ Terms = [] }] = input;
  if (!Terms.length) return 'Terms needs at least one row.';
  const powers = new Set();
  for (const [power, factor] of Terms) {
    if (power === null || power < 0 || power > 100) return 'Every power must be between 0 and 100.';
    if (powers.has(power)) return `power ${power} appears twice in Terms.`;
    if (factor === null || factor === 0 || factor < -100 || factor > 100) return `The factor of power ${power} must be a nonzero number between -100 and 100.`;
    powers.add(power);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const factors = [-100, -12, -3, -1, 1, 2, 7, 10, 100];
  const pool = small
    ? (rand() < 0.5 ? [0, 1, 2, 3, 4, 5] : [0, 1, 2, 9, 10, 11, 99, 100])
    : Array.from({ length: 101 }, (_, i) => i);
  const chosen = pool.filter(() => rand() < (small ? 0.6 : 0.9));
  if (!chosen.length) chosen.push(pool[Math.floor(rand() * pool.length)]);
  while (small && chosen.length > 8) chosen.splice(Math.floor(rand() * chosen.length), 1);
  // Rows arrive in a shuffled order, so the query must sort by power itself.
  for (let i = chosen.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chosen[i], chosen[j]] = [chosen[j], chosen[i]];
  }
  const Terms = chosen.map(power => [power, small ? factors[Math.floor(rand() * factors.length)] : (rand() < 0.5 ? -1 : 1) * (1 + Math.floor(rand() * 100))]);
  return [{ Terms }];
}
